// src/Telas/Detalhes.js
import React from 'react';
import { useData } from '../DataContext';

function Detalhes() {
  const { data } = useData();

  return (
    <div className="App min-h-screen bg-gray-100 flex items-center justify-center">
      <div className="w-full max-w-md p-6 bg-white rounded-lg shadow-md">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Detalhes do Cadastro</h1>
        {data.length === 0 ? (
          <p>Nenhum dado cadastrado.</p>
        ) : (
          data.map((item, index) => (
            <div key={index} className="mb-4">
              <p><strong>Nome Completo:</strong> {item.nomeCompleto}</p>
              <p><strong>Data de Nascimento:</strong> {item.dataNascimento}</p>
              <p><strong>Telefone:</strong> {item.telefone}</p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default Detalhes;
